import {methodConfig,blockDay,currentDay} from './study-method.js';
export const planLabel=n=>'Dia '+String(n).padStart(2,'0');
export function durationText(seconds=0){const n=Math.max(0,Math.floor(seconds));return `${String(Math.floor(n/3600)).padStart(2,'0')}:${String(Math.floor(n%3600/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
export function studiedBefore(c,b,data){return methodConfig(b.method).studied_before||(data.method_studies||[]).some(s=>s.student_id===c.student_id&&s.topic_key===b.topic_key&&s.studied_at&&(s.cycle_id!==c.id||s.studied_day<currentDay(c,data.progress)));}
export function visibleSteps(c,b,data){const cfg=methodConfig(b.method),p=data.profiles.find(p=>p.id===c.student_id);return cfg.steps.filter(s=>s.kind!=='flashcard'||((p?.plan==='Estratégico'||p?.role==='admin')&&blockDay(b,c)>=8&&studiedBefore(c,b,data)&&(data.flashcards||[]).some(f=>f.topic_key===b.topic_key)));}
export function reviewHasCards(r,data){const study=data.method_studies.find(s=>s.id===r.study_id);return r.status!=='cancelled'&&r.due_day>=8&&study?.studied_at&&(study.config?.flashcard||study.config?.steps?.some(st=>st.kind==='flashcard'))&&(data.flashcards||[]).some(f=>f.topic_key===study.topic_key&&f.review_keys.includes(r.review_key));}
export function dayTasks(c,data){const day=currentDay(c,data.progress),tasks=[];for(const b of c.blocks){const n=blockDay(b,c);if(n>day)continue;const study=data.method_studies.find(s=>s.cycle_id===c.id&&s.block_id===b.id);for(const step of visibleSteps(c,b,data)){const done=!!study?.flags?.[step.id];if(n<day&&done)continue;tasks.push({b,step,done});}}
for(const r of data.method_reviews.filter(r=>r.cycle_id===c.id&&r.due_day<=day&&r.status!=='cancelled')){if(r.due_day===day||r.status!=='completed')tasks.push({r,done:r.status==='completed'});if(reviewHasCards(r,data)){const done=(data.flashcard_runs||[]).some(x=>x.review_id===r.id&&x.completed_at);if(r.due_day===day||!done)tasks.push({r,flash:true,done});}}return tasks;}
export function flashScore(runs){const values=runs.flatMap(r=>Object.values(r.answers||{}));return {total:values.length,correct:values.filter(x=>x==='correct').length,wrong:values.filter(x=>x==='wrong').length,forgot:values.filter(x=>x==='forgot').length};}
export function sessionClock(session,now=Date.now(),syncedAt=now){const extra=session.status==='running'?Math.min(30,Math.max(0,(now-syncedAt)/1000)):0;const limit=session.phase==='focus'?Math.min(session.focus_seconds,session.target_seconds-session.focused_seconds+session.phase_seconds):session.break_seconds;const add=Math.min(extra,Math.max(0,limit-session.phase_seconds));return {focused:Number(session.focused_seconds)+(session.phase==='focus'?add:0),remaining:Math.max(0,limit-session.phase_seconds-add),goal:Math.max(0,session.target_seconds-session.focused_seconds-(session.phase==='focus'?add:0))};}
